package com.slakey.anysend.bridge

import android.content.Context
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import tsnetbridge.Tsnetbridge
import java.net.NetworkInterface

/**
 * Wraps the Tailscale tsnet AAR (generated by gomobile bind from
 * go/tsnetbridge). Provides login, peer discovery, and raw
 * dial/listen over the Tailscale network.
 */
object TailscaleManager {

    private val gson = Gson()
    private var started = false

    /**
     * Log in to Tailscale using an auth key and start the embedded node.
     * @return true on success
     */
    suspend fun login(context: Context, authKey: String): Boolean = withContext(Dispatchers.IO) {
        if (started) return@withContext true
        val stateDir = context.filesDir.absolutePath + "/tailscale-state"
        java.io.File(stateDir).mkdirs()
        val hostname = android.os.Build.MODEL.replace(" ", "-")
        // netmon needs the interface list before tsnet starts: Android forbids
        // the netlink call Go's net.Interfaces() relies on.
        Tsnetbridge.setInterfaces(interfaceSpecJson())
        // gomobile maps Go int -> int; Start returns 0 on success
        val rc = Tsnetbridge.start(authKey, stateDir, hostname)
        started = (rc == 0L)
        started
    }

    /**
     * Enumerate this device's network interfaces as JSON for Go's netmon.
     *
     * Android blocks netlink, so Go cannot discover interfaces itself; the
     * sanctioned java.net.NetworkInterface API is used instead. Addresses are
     * issued in CIDR form so Go can rebuild them without netlink.
     */
    private fun interfaceSpecJson(): String {
        val arr = JSONArray()
        try {
            for (intf in NetworkInterface.getNetworkInterfaces()) {
                val addrs = JSONArray()
                for (ia in intf.interfaceAddresses) {
                    val host = ia.address?.hostAddress ?: continue
                    // IPv6 host addresses can carry a scope id, e.g. fe80::1%wlan0.
                    addrs.put("${host.substringBefore('%')}/${ia.networkPrefixLength}")
                }
                arr.put(
                    JSONObject()
                        .put("name", intf.name)
                        .put("index", intf.index)
                        .put("mtu", intf.mtu)
                        .put("up", intf.isUp)
                        .put("addrs", addrs)
                )
            }
        } catch (e: Exception) {
            // Return whatever was collected; an empty list is still better
            // than letting startup fail on netlink.
        }
        return arr.toString()
    }

    fun isStarted(): Boolean {
        return started && Tsnetbridge.isStarted()
    }

    private val networkLayer by lazy { com.slakey.anysend.protocol.TailscaleNetworkLayer() }

    /**
     * The tsnet-backed socket layer, or null when the embedded node is down.
     * Callers use it to reach 100.x peers that the system stack cannot route.
     */
    fun currentNetworkLayer(): com.slakey.anysend.protocol.NetworkLayer? {
        return if (isStarted()) networkLayer else null
    }

    /**
     * Return the Go-side error from the most recent failed login, or null.
     * Native startup failures are otherwise invisible: Android discards the
     * process's stderr, so the message is surfaced from Go explicitly.
     */
    fun lastError(): String? {
        return try {
            Tsnetbridge.lastError().ifEmpty { null }
        } catch (e: Exception) {
            null
        }
    }

    data class PeerInfo(
        val hostName: String,
        val tailscaleIP: String,
        val online: Boolean
    )

    data class SelfInfo(
        val hostName: String,
        val tailscaleIP: String
    )

    suspend fun getSelfInfo(): SelfInfo? = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.getSelfInfo()
        if (json.isNullOrEmpty()) null else gson.fromJson(json, SelfInfo::class.java)
    }

    suspend fun getPeers(): List<PeerInfo> = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.getPeers()
        if (json.isNullOrEmpty()) return@withContext emptyList()
        val type = object : TypeToken<List<PeerInfo>>() {}.type
        gson.fromJson(json, type) ?: emptyList()
    }

    /**
     * Dial a TCP/UDP address through the Tailscale network.
     * @return connection handle (>0) or -1 on error
     */
    suspend fun dial(network: String, addr: String): Long = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.dial(network, addr)
        parseHandle(json)
    }

    /**
     * Dial a TLS connection through the Tailscale network.
     *
     * Official LocalSend peers serve HTTPS with a self-signed certificate, so
     * verification is skipped on the Go side (still encrypted end to end).
     * @return connection handle (>0) or -1 on error
     */
    suspend fun dialTls(network: String, addr: String): Long = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.dialTls(network, addr)
        parseHandle(json)
    }

    /**
     * Listen on a Tailscale address.
     * @return listener handle (>0) or -1 on error
     */
    suspend fun listen(network: String, addr: String): Long = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.listen(network, addr)
        parseHandle(json)
    }

    suspend fun accept(listenerHandle: Long): Long = withContext(Dispatchers.IO) {
        val json = Tsnetbridge.accept(listenerHandle)
        parseHandle(json)
    }

    suspend fun read(handle: Long, maxLen: Int): ByteArray? = withContext(Dispatchers.IO) {
        try {
            Tsnetbridge.read(handle, maxLen.toLong())
        } catch (e: Exception) {
            null
        }
    }

    suspend fun write(handle: Long, data: ByteArray): Int = withContext(Dispatchers.IO) {
        try {
            Tsnetbridge.write(handle, data).toInt()
        } catch (e: Exception) {
            -1
        }
    }

    fun closeConn(handle: Long) {
        Tsnetbridge.closeConn(handle)
    }

    fun closeListener(handle: Long) {
        Tsnetbridge.closeListener(handle)
    }

    fun close() {
        Tsnetbridge.close()
        started = false
    }

    private fun parseHandle(json: String): Long {
        // json = {"handle":N} or {"error":"..."}
        return try {
            val obj = gson.fromJson(json, Map::class.java)
            val h = obj["handle"]
            if (h is Number) h.toLong() else -1L
        } catch (e: Exception) {
            -1L
        }
    }
}
